 @Test void cambioConcurrenteConfirmaUnaSolaRevision()throws Exception{
  f.otorgar(f.headA,"COORDINADOR","AREA_B");f.otorgar(f.profA,"PROFESIONAL","AREA_B");var c=f.caso("AREA_A",f.headA,f.profA);var gate=new CountDownLatch(1);
  try(var pool=Executors.newFixedThreadPool(2)){var one=pool.submit(()->change(gate,c));var two=pool.submit(()->change(gate,c));gate.countDown();var results=new ArrayList<>(List.of(one.get(8,TimeUnit.SECONDS),two.get(8,TimeUnit.SECONDS)));Collections.sort(results);assertEquals(List.of(200,409),results);}assertEquals(2,f.core.historialArea(f.a(f.headA),c).size());
 }
